function after(){ var i=$('dq-ph-q'); if(i){ i.oninput=function(){ V.a.q=i.value; var b=$('dq-ph-l'); if(b) b.innerHTML=pharmList(); }; }
  var t=$('dq-note'); if(t){ t.oninput=function(){ var k=t.getAttribute('data-k'); var o=PV.notes[k]||{}; o.x=t.value; o.at=Date.now(); o.t=t.getAttribute('data-t')||''; PV.notes[k]=o; if(!t.value.trim()) delete PV.notes[k]; saveMe(); var s=$('dq-note-s'); if(s) s.textContent='حُفظ على جهازك'; }; } }
