function topbar(Lx){ return '<div class="dq-tb">'+crumbs([['تعلّم','learn'],[D().title,'home']].concat(Lx||[]))+(ST.lv?'<button type="button" class="dq-lvb" data-a="pick" aria-label="طريقك: '+LV[lv()].n+'، غيّره">'+sv(LV[lv()].ic,16)+'<span>طريقك: <b>'+LV[lv()].n+'</b></span><em>غيّر</em></button>':'')+'</div>'; }

