   +['kid','yth','adl'].map(function(k){ var o=LV[k], on=ST.lv===k; return '<button type="button" class="pc '+k+(on?' on':'')+'" data-a="setlv" data-v="'+k+'" aria-pressed="'+on+'"><span class="ar">'+sv(o.ic,34,1.6)+'</span><b>'+o.n+'</b><small>'+o.age+'</small><p>'+o.line+'</p><span class="go">'+(on?'طريقك الحالي':'اختر هذا الطريق')+sv('next',14,2.4)+'</span></button>'; }).join('')
