var TOOLS=[['pharmacy','jar','صيدلية القلب','ابحث عن الداء، تجد دواءه بنص ابن القيم',0],['effects','map','خريطة آثار الذنوب','كل أثر بطاقة، اقلبها لترى ما قاله الكتاب',0],['gates','gate','حراسة الأبواب','الأبواب الأربعة والثغور، ومراجعتك اليومية',0],['dua','dua','الدعاء المستجاب','الشروط والموانع وأوقات الإجابة',0],
  ['rajaa','scale','ميزان الرجاء والخوف','الفرق بين حسن الظن والغرور',1],['sins4','grid4','أقسام الذنوب','ملكية وشيطانية وسبعية وبهيمية',1],['love','ladder','مراتب المحبة ولذات الدنيا','سلّم المحبة، وأنواع اللذات الثلاثة',1],['plan','plan','خطتي للدواء','ما جمعته من الأدوية، مرتباً للطباعة',0],['notes','pen','دفتر القلب','تأملاتك الخاصة، على جهازك وحده',0]];
