 'mt-b':function(v,el){ var s=V.a[v], b=+el.getAttribute('data-i'); if(s.cur==null) return; Object.keys(s.m).forEach(function(k){ if(s.m[k]===b) delete s.m[k]; }); s.m[s.cur]=b; s.cur=null; keep(render); },
 'mt-k':function(v){ V.a[v].chk=1; keep(render); },
 'or-u':function(v,el){ var o=V.a[v].o, p=+el.getAttribute('data-i'); var t=o[p]; o[p]=o[p-1]; o[p-1]=t; keep(render); },
 'or-d':function(v,el){ var o=V.a[v].o, p=+el.getAttribute('data-i'); var t=o[p]; o[p]=o[p+1]; o[p+1]=t; keep(render); },
 'or-k':function(v){ V.a[v].chk=1; keep(render); },
 'pl-t':function(v,el){ var s=V.a[v].sel, i=el.getAttribute('data-i'); if(s[i]) delete s[i]; else s[i]=1; keep(render); },
 'pl-a':function(v,el){ var s=stBy(el.getAttribute('data-s')), a=[L(s).act,L(s).act2][+v.split('-').pop()]||{}, sel=V.a[v].sel; Object.keys(sel).forEach(function(i){ var x=itX((a.items||[])[i]); if(x&&!PV.plan.some(function(p){ return p.x===x; })) PV.plan.push({x:x,s:s.k,at:Date.now()}); }); saveMe(); toastX('أُضيف إلى خطتك','success'); V.a[v].sel={}; keep(render); },
 'gd-o':function(v,el){ var o=V.a[v].op, i=el.getAttribute('data-i'); o[i]=1; keep(render); },
 'gd-a':function(v,el){ var s=stBy(el.getAttribute('data-s')), a=[L(s).act,L(s).act2][+v.split('-').pop()]||{}; (a.items||[]).forEach(function(it){ var k=it.k||it.h||it.a||'', x=(k?k+': ':'')+(it.x||it.b||''); if(!PV.plan.some(function(p){ return p.x===x; })) PV.plan.push({x:x,s:s.k,at:Date.now()}); }); saveMe(); toastX('أُضيف الحراس إلى خطتك','success'); },
 'qz-o':function(v){ var z=V.a.qz; if(z.ch!=null) return; z.ch=+v; if(z.ch===0) z.ok++; keep(render); },
